static string MaskPan(string? pan)
{
    if (string.IsNullOrEmpty(pan)) return "";
    if (pan.Length <= 10) return new string('*', pan.Length);
    return string.Concat(pan[..6], new string('*', pan.Length - 10), pan[^4..]);
}

